import { createHash } from "node:crypto";
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const migrations = resolve(root, "server/migrations");
const files = (await readdir(migrations))
  .filter((file) => /^\d+.*\.sql$/.test(file))
  .sort();
const sections = [
  "-- TroGon schema for a NEW MySQL 8 database.",
  "-- Generated by node scripts/export-schema.mjs from server/migrations.",
  "-- Contains schema and initial configuration only; no users, passwords or sessions.",
  "-- The current localhost database is already initialized; no re-import is needed.",
  "CREATE DATABASE IF NOT EXISTS `trogon` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;",
  "USE `trogon`;",
  "SET NAMES utf8mb4;",
  "CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, checksum CHAR(64) NOT NULL, appliedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));",
];
for (const file of files) {
  const sql = await readFile(resolve(migrations, file), "utf8");
  const checksum = createHash("sha256").update(sql).digest("hex");
  sections.push(
    `\n-- Migration: ${file}`,
    sql.trim(),
    `INSERT IGNORE INTO schema_migrations (version, checksum) VALUES ('${file}', '${checksum}');`,
  );
}
await mkdir(resolve(root, "database"), { recursive: true });
await writeFile(resolve(root, "database/trogon-schema.sql"), sections.join("\n") + "\n", "utf8");
console.log("Exported database/trogon-schema.sql (schema only).");
